/*==============================================================================
IMAGE — Final renderer (raymarch Voronoi faces with edges always visible)
==============================================================================

WHAT THIS PASS DOES
• Raymarches inside the axis-aligned cube and shades a proxy SDF of the
  Voronoi cell faces using the 4 nearest site IDs from Buffer B.

PIPELINE
1) Camera & AA:
   • Auto-rotate unless mouse is active; ordered dithering via bayer4x4.
   • Optional supersampling with per-sample jitter.

2) Box entry:
   • Intersect ray with cube [-CUBE_SIZE, +CUBE_SIZE]; skip if miss.

3) Per-step:
   • Convert hit point → voxel index; fetch ivec4 IDs from Buffer B.
   • If any ID < 0, advance and continue (treat as empty region).
   • Fetch positions of those 4 sites from Buffer A.
   • Evaluate face proxy SDF via pairwise distance differences (periodic).
   • If near a face (|SDF| small):
       – Optional band-pass opacity from Buffer C (.r) for size/spacing.
       – Choose base color (solid, or derived from aspect via Buffer D).
       – Compute edgeWeight by comparing distance differences (multi-edge hint).
       – Blend edges to be always visible; compute normal by gradient of map().
       – Simple diffuse + rim lighting; fog toward background.

PERIODICITY
• All distances use boundaryDist(..., 2*CUBE_SIZE) so faces/edges are seamless.

INPUTS / OUTPUTS
• iChannel0 → Buffer A (pos.xyz, R)
• iChannel1 → Buffer B (4 nearest IDs per voxel)
• iChannel2 → Buffer D (vel.xyz, smoothed_aspect)  // aspect is CONTINUOUS in .w
• iChannel3 → Buffer C (norm_ratio)                 // for optional band-pass
• fragColor → final shaded color
==============================================================================*/


#define MAX_STEPS 80
#define USE_SUPERSAMPLING 1
#define SAMPLE_COUNT 4

// The band-pass filter uses these settings from Common
// to determine which edges to show based on site "size".
const float RATIO_MAX = 2.0;
const float S_MIN  = 0.05;
const float S_MAX  = 0.95;
const float S_SOFT = 0.6;


// --- Helper Functions ---

float hash12(vec2 p){ vec3 p3=fract(vec3(p.xyx)*.1031); p3+=dot(p3,p3.yzx+33.33); return fract((p3.x+p3.y)*p3.z); }

// Finds the 3 nearest sites and their distances to point p.
void measuresAt(vec3 p, out float d0, out float d1, out float d2, out int s0, out int s1, out int s2) {
    ivec3 c = ivec3(floor((p/(CUBE_SIZE*2.)+.5)*float(VOXEL_DIM)));
    ivec4 nIds = ivec4(texelFetch(iChannel1, to2D(clamp(c,0,VOXEL_DIM-1)), 0));

    if(nIds.x < 0 || nIds.y < 0 || nIds.z < 0 || nIds.w < 0) {
        s0=s1=s2=-1;
        d0=d1=d2=CUBE_SIZE;
        return;
    }

    float s = CUBE_SIZE * 2.0;
    int i0 = nIds.x, i1 = nIds.y, i2 = nIds.z, i3 = nIds.w;
    float m0 = boundaryDist(p, getSiteData(iChannel0, i0).xyz, s);
    float m1 = boundaryDist(p, getSiteData(iChannel0, i1).xyz, s);
    float m2 = boundaryDist(p, getSiteData(iChannel0, i2).xyz, s);
    float m3 = boundaryDist(p, getSiteData(iChannel0, i3).xyz, s);

    sort4(m0, m1, m2, m3, i0, i1, i2, i3);

    d0=m0; d1=m1; d2=m2;
    s0=i0; s1=i1; s2=i2;
}

// Signed Distance Function for a Voronoi edge.
// An edge is where a point is equidistant to at least 3 sites.
float edgeSDF(vec3 p){
    float d0, d1, d2; int s0, s1, s2;
    measuresAt(p, d0, d1, d2, s0, s1, s2);
    if (s0 < 0) return CUBE_SIZE; // Return large distance if in empty space

    // An edge is where d0, d1, and d2 are very close.
    // This defines a thick edge based on two differences.
    return max(abs(d1 - d0) - EDGE_THICKNESS*0.5, abs(d2 - d1) - EDGE_THICKNESS*0.5);
}

// Calculates the surface normal by sampling the SDF.
vec3 getNormal(vec3 p){
    vec2 e = vec2(EDGE_SHARPNESS * 0.1, 0);
    return normalize(vec3(
        edgeSDF(p + e.xyy) - edgeSDF(p - e.xyy),
        edgeSDF(p + e.yxy) - edgeSDF(p - e.yxy),
        edgeSDF(p + e.yyx) - edgeSDF(p - e.yyx)
    ));
}

// Band-pass filter function. Returns 1.0 if r is inside the band, 0.0 otherwise.
float bandWeight(float r){
    float win  = smoothstep(S_MIN - S_SOFT, S_MIN + S_SOFT, r);
    float wout = 1.0 - smoothstep(S_MAX - S_SOFT, S_MAX + S_SOFT, r);
    return clamp(win * wout, 0.0, 1.0);
}

// Main raymarching function.
vec3 raymarch(vec2 fragCoord, vec2 jitter){
    vec3 backgroundColor = vec3(0.047,0.055,0.051);
    float ditherThreshold = bayer4x4(fragCoord + jitter);

    // Camera setup
    float angleH=iTime*AUTO_ROTATE_SPEED, angleV=0.;
    if(iMouse.z>0.){ angleH=(iMouse.x/iResolution.x-.5)*6.28318;
                     angleV=(iMouse.y/iResolution.y-.5)*3.14159;
                     angleV=clamp(angleV,-1.4,1.4); }
    float sh=sin(angleH), ch=cos(angleH);
    float sv=sin(angleV), cv=cos(angleV);
    mat3 rotY=mat3(ch,0,-sh, 0,1,0, sh,0,ch);
    mat3 rotX=mat3(1,0,0, 0,cv,sv, 0,-sv,cv);
    mat3 rot = rotX*rotY;

    vec3 ro=transpose(rot)*vec3(0.,0.,2.5);
    vec2 uv=(fragCoord+jitter-.5*iResolution.xy)/iResolution.y;
    vec3 rd=transpose(rot)*normalize(vec3(uv,-1.5));

    // Box intersection
    vec3 tMin=(vec3(-CUBE_SIZE)-ro)/rd, tMax=(vec3(CUBE_SIZE)-ro)/rd;
    vec3 t1=min(tMin,tMax), t2=max(tMin,tMax);
    float tNear=max(max(t1.x,t1.y),t1.z), tFar=min(min(t2.x,t2.y),t2.z);
    if(tNear>tFar||tFar<0.) return backgroundColor;

    float t=max(0.,tNear);
    for(int i=0;i<MAX_STEPS;i++){
        vec3 p=ro+rd*t;
        float dist=edgeSDF(p);

        if(dist < EDGE_SHARPNESS * 0.1){
            float d0,d1,d2; int s0,s1,s2;
            measuresAt(p, d0,d1,d2, s0,s1,s2);
            if (s0<0||s1<0||s2<0) { t+=0.01; if(t>tFar)break; continue; }

            // Fetch ratios from Buffer C (iChannel3)
            float r0 = texelFetch(iChannel3, siteUV(s0), 0).r * RATIO_MAX;
            float r1 = texelFetch(iChannel3, siteUV(s1), 0).r * RATIO_MAX;
            float r2 = texelFetch(iChannel3, siteUV(s2), 0).r * RATIO_MAX;

            // Apply band-pass filter to each site's ratio
            float b0 = bandWeight(r0);
            float b1 = bandWeight(r1);
            float b2 = bandWeight(r2);

            // Combine weights to get final edge visibility
            float wTri;
            #if BAND_MODE == 0
                wTri = max(b0, max(b1, b2)); // Widest visibility
            #elif BAND_MODE == 2
                wTri = min(b0, min(b1, b2)); // Strictest visibility
            #else
                float sA=min(b0,min(b1,b2)); float sC=max(b0,max(b1,b2));
                float sB=b0+b1+b2 - sA - sC; wTri = sB; // Median visibility
            #endif

            float vis = wTri;
            if(vis < ditherThreshold){ t+=max(dist,.005); if(t>tFar)break; continue; }

            // Lighting
            vec3 n=transpose(rot)*getNormal(p);
            vec3 l=normalize(vec3(.8,.9,.6));
            float diff=max(0.,dot(n,l));
            vec3 v=normalize(-(ro+rd*t));
            float rim_factor=pow(1.-max(0.,dot(v,n)),2.)*VIZ_RIM_LIGHT_STRENGTH;
            vec3 rim=vec3(rim_factor);
            float lighting=diff*VIZ_DIFFUSE_STRENGTH+VIZ_AMBIENT_STRENGTH;

            // Use the ratio of the nearest site for tinting the edge color
            float tR0 = clamp((r0 - S_MIN) / max(S_MAX - S_MIN, 1e-6), 0.0, 1.0);
            vec3 sizeTint = mix(SIZE_TINT_A, SIZE_TINT_B, tR0);

            vec3 surfaceColor = mix(backgroundColor, sizeTint, vis) * lighting + rim;

            float fog=smoothstep(tFar,tNear,t);
            return mix(backgroundColor,surfaceColor,fog);
        }

        t+=max(dist,.005);
        if(t>tFar) break;
    }
    return backgroundColor;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    #if USE_SUPERSAMPLING
        vec3 color=vec3(0.);
        for(int s=0;s<SAMPLE_COUNT;s++){
            vec2 o=vec2(hash12(fragCoord+float(s)*100.)-.5, hash12(fragCoord+float(s)*200.+13.)-.5)*.5;
            color+=raymarch(fragCoord,o);
        }
        fragColor=vec4(color/float(SAMPLE_COUNT),1.);
    #else
        fragColor=vec4(raymarch(fragCoord,vec2(0.)),1.);
    #endif
}

/*==============================================================================
BUFFER A — Site state (position + radius) with size controller
==============================================================================

WHAT THIS PASS PRODUCES
• A site atlas where each texel holds the current site position and radius:
  vec4(pos.x, pos.y, pos.z, R).

SEEDING & UPDATE
• Frames < 5: seed positions uniformly across the whole cube using hash33(),
  set R = INITIAL_RADIUS, vel = 0 (read-only here).
• Subsequent frames: read previous A for (pos,R) and D for (vel, aspect).

SIZE CONTROLLER (HYSTERESIS AROUND TH_LO/TH_HI)
• Reads smoothed_aspect from D.w and compares to dead-band mid and width.
• Computes a signed control signal u that shrinks (aspect > TH_HI) or grows
  (aspect < TH_LO), clamped by CTRL_MAX_FRAC_STEP.
• Radius is updated multiplicatively and clamped to [MIN_RADIUS, MAX_RADIUS].

INTEGRATION & WRAP
• Updates position: pos += vel (from D), then wraps toroidally into the cube.

INPUTS / OUTPUTS
• iChannel0 → previous Buffer A (self)
• iChannel1 → Buffer D (vel.xyz, smoothed_aspect)
• fragColor → vec4(pos.xyz, R)

RESULT
• Per-site state advanced one step with a stable, bounded size controller that
  reacts only when aspect exits the hysteresis band.
==============================================================================*/


void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    ivec2 p = ivec2(fragCoord);
    if (p.x >= SITE_ATLAS_W || p.y >= SITE_ATLAS_H) { fragColor = vec4(0); return; }
    int siteId = p.y * SITE_ATLAS_W + p.x;
    if (siteId >= MAX_SITES) { fragColor = vec4(0); return; }

    vec3 pos; float R;
if (iFrame < 5) {
    // seed anywhere in the cube, not just one corner
    pos = hash33(vec3(float(siteId), float(siteId)*0.1, float(siteId)*0.2))
          * (CUBE_SIZE * 0.999);   // tiny shrink to avoid exact boundary
    R = INITIAL_RADIUS;
} else {
    vec4 prevA = texelFetch(iChannel0, p, 0);
    pos = prevA.xyz; R = prevA.w;
}


    vec4 phys = texelFetch(iChannel1, p, 0);
    vec3 vel  = (iFrame < 5) ? vec3(0.0) : phys.xyz;
    float smoothed_aspect = phys.w;   // direct, continuous

    // Controller (unchanged)
    float R_prev   = R;
    float center   = 0.5 * (TH_HI + TH_LO);
    float halfBand = 0.5 * (TH_HI - TH_LO);
    float err      = smoothed_aspect - center;

    float u = 0.0;
    if (err >  halfBand) u = -CTRL_GAIN * (err - halfBand);
    else if (err < -halfBand) u =  CTRL_GAIN * (-halfBand - err);

    float d = clamp(u, -CTRL_MAX_FRAC_STEP, CTRL_MAX_FRAC_STEP);
    R *= (1.0 + d);
    R = clamp(R, MIN_RADIUS, MAX_RADIUS);

    pos += vel;
    pos = mod(pos + CUBE_SIZE, CUBE_SIZE*2.) - CUBE_SIZE;

    fragColor = vec4(pos, R);
}

/*==============================================================================
BUFFER B — 3D voxel field of 4-nearest site IDs
(fixed 8×8 voxel atlas, periodic distance, safe OOB, seed-once + JFA on interval)
==============================================================================

WHAT THIS PASS PRODUCES
• A 64×64×64 voxel grid (packed in a 512×512 atlas) where each texel stores
  the IDs of the 4 nearest sites: vec4(best0, best1, best2, best3).
• Image/D use these IDs to evaluate Voronoi faces/edges/normals.

ATLAS LAYOUT (CONSISTENT)
• VOXEL_DIM = 64, SLICES_PER_ROW = 8  →  64×64×64 → 512×512 atlas.
• Always map via Common helpers:
  - from2D(ivec2)  : pixel → (x,y,z) voxel
  - to2D(ivec3)    : voxel → pixel
  - voxelToWorld() : voxel center → world position
• Pixels outside the atlas rectangle write vec4(-1) (NO discard).

PERIODIC SPACE (SEAMLESS)
• Distances are computed with wrapping over ±CUBE_SIZE:
  boundaryDist(p, sitePos, 2*CUBE_SIZE)  (and boundaryDelta when needed).
• Ensures neighbors are correct across domain boundaries.

UPDATE CADENCE (NO BRUTE FORCE AFTER FRAME 0)
1) Frame 0 (one-time brute seed):
   - Iterate over ALL sites and keep the best 4 (sorted) per voxel.
2) Subsequent frames:
   - Only on update frames (iFrame % updateInterval == 0):
       • Start from last frame’s 4 IDs (iChannel1), re-evaluate their distances.
       • Run a small Jump-Flood refinement with steps 8 → 4 → 2 → 1.
         For each step, visit neighbor voxels at that stride and try their 4 IDs.
   - On non-update frames:
       • Simply reuse last frame’s result (copy from iChannel1) with no work.

NEGATIVE-ID CONTRACT
• This pass writes -1 for OOB/invalid; downstream treats <0 as “ignore”.
• Prevents undefined reads and eliminates vertical slab/stripe artifacts.

INPUTS / OUTPUTS
• iChannel0 → Buffer A (site atlas: pos.xyz, R)
• iChannel1 → previous Buffer B (cached 4-ID field)
• fragColor → vec4(best0, best1, best2, best3) in atlas coords

PERFORMANCE KNOBS
• updateInterval : run JFA every N frames (accuracy vs. cost)
• VOXEL_DIM      : voxel resolution (↑ = crisper, heavier)
• SLICES_PER_ROW : packing (kept consistent with helpers)

PITFALLS AVOIDED
• No discard; OOB writes vec4(-1).
• All atlas reads/writes go through to2D()/from2D().
• Distances are periodic; no cracks at ±CUBE_SIZE boundaries.

RESULT
• Stable, seam-free 4-nearest IDs with low per-frame cost by reusing the
  previous field most frames and refining only on the chosen interval.
==============================================================================*/


/*==============================================================================
BUFFER B — 3D Voxel Field of Nearest Sites
(fixed 8×8 voxel atlas, safe OOB, periodic distance,
 seed-once + JFA refine + lightweight per-frame refresh)
==============================================================================*/

#define DO_LIGHT_REFRESH 1     // 1 = do a very cheap step=1 refine on non-update frames
#define LIGHT_STEP       1     // step size for the light refresh

// Insert candidate (ignore <0 & duplicates), keep sorted distances asc
void updateClosest4(inout ivec4 ids, inout vec4 dists, vec3 p, int newId, sampler2D siteSampler)
{
    if (newId < 0) return;
    if (newId == ids.x || newId == ids.y || newId == ids.z || newId == ids.w) return;

    float d = boundaryDist(p, getSiteData(siteSampler, newId).xyz, CUBE_SIZE * 2.0);

    if (d < dists.x) {
        dists = vec4(d, dists.xyz);
        ids   = ivec4(newId, ids.xyz);
    } else if (d < dists.y) {
        dists = vec4(dists.x, d, dists.yz);
        ids   = ivec4(ids.x, newId, ids.yz);
    } else if (d < dists.z) {
        dists = vec4(dists.xy, d, dists.w);
        ids   = ivec4(ids.xy, newId, ids.w);
    } else if (d < dists.w) {
        dists.w = d;
        ids.w   = newId;
    }
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // --- Fixed 64×64×64 grid packed as 8×8 slices → 512×512 atlas ---
    ivec2 atlasSize = ivec2(SLICES_PER_ROW * VOXEL_DIM,
                            VOXEL_DIM * (VOXEL_DIM / SLICES_PER_ROW));

    // SAFE OOB: write -1s (no discard) so downstream ignores this texel
    if (any(greaterThanEqual(ivec2(fragCoord), atlasSize))) {
        fragColor = vec4(-1.0);
        return;
    }

    // Map to voxel + world position
    ivec2 uv  = ivec2(fragCoord);
    ivec3 v   = from2D(uv);
    vec3  p   = voxelToWorld(v);
    float L   = CUBE_SIZE * 2.0;

    // Cadence
    const int updateInterval = 10;
    bool seedFrame  = (iFrame == 0);
    bool fullUpdate = (iFrame % updateInterval == 0);

    // Start set
    ivec4 bestIds   = ivec4(-1);
    vec4  bestDists = vec4(1e6);

    if (seedFrame) {
        // ---- Frame 0: one-time brute seed over all sites ----
        for (int id = 0; id < MAX_SITES; ++id) {
            updateClosest4(bestIds, bestDists, p, id, iChannel0);
        }
    } else {
        // ---- Subsequent frames: begin from last frame’s IDs ----
        ivec4 prevIds = ivec4(texelFetch(iChannel1, uv, 0));

        // Re-evaluate current 4 (keeps order/dist fresh even on cheap frames)
        for (int c = 0; c < 4; ++c) {
            int id = prevIds[c];
            updateClosest4(bestIds, bestDists, p, id, iChannel0);
        }

        // ---- Refinement ----
        // Full JFA: 8 → 4 → 2 → 1 every updateInterval frames
        if (fullUpdate) {
            // pass 0
            for (int dz = -1; dz <= 1; ++dz)
            for (int dy = -1; dy <= 1; ++dy)
            for (int dx = -1; dx <= 1; ++dx) {
                if (dx == 0 && dy == 0 && dz == 0) continue;
                ivec3 vn = v + ivec3(dx, dy, dz) * 8;
                if (any(lessThan(vn, ivec3(0))) || any(greaterThanEqual(vn, ivec3(VOXEL_DIM)))) continue;
                ivec4 nIds = ivec4(texelFetch(iChannel1, to2D(vn), 0));
                updateClosest4(bestIds, bestDists, p, nIds.x, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.y, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.z, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.w, iChannel0);
            }
            // pass 1
            for (int dz = -1; dz <= 1; ++dz)
            for (int dy = -1; dy <= 1; ++dy)
            for (int dx = -1; dx <= 1; ++dx) {
                if (dx == 0 && dy == 0 && dz == 0) continue;
                ivec3 vn = v + ivec3(dx, dy, dz) * 4;
                if (any(lessThan(vn, ivec3(0))) || any(greaterThanEqual(vn, ivec3(VOXEL_DIM)))) continue;
                ivec4 nIds = ivec4(texelFetch(iChannel1, to2D(vn), 0));
                updateClosest4(bestIds, bestDists, p, nIds.x, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.y, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.z, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.w, iChannel0);
            }
            // pass 2
            for (int dz = -1; dz <= 1; ++dz)
            for (int dy = -1; dy <= 1; ++dy)
            for (int dx = -1; dx <= 1; ++dx) {
                if (dx == 0 && dy == 0 && dz == 0) continue;
                ivec3 vn = v + ivec3(dx, dy, dz) * 2;
                if (any(lessThan(vn, ivec3(0))) || any(greaterThanEqual(vn, ivec3(VOXEL_DIM)))) continue;
                ivec4 nIds = ivec4(texelFetch(iChannel1, to2D(vn), 0));
                updateClosest4(bestIds, bestDists, p, nIds.x, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.y, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.z, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.w, iChannel0);
            }
            // pass 3
            for (int dz = -1; dz <= 1; ++dz)
            for (int dy = -1; dy <= 1; ++dy)
            for (int dx = -1; dx <= 1; ++dx) {
                if (dx == 0 && dy == 0 && dz == 0) continue;
                ivec3 vn = v + ivec3(dx, dy, dz) * 1;
                if (any(lessThan(vn, ivec3(0))) || any(greaterThanEqual(vn, ivec3(VOXEL_DIM)))) continue;
                ivec4 nIds = ivec4(texelFetch(iChannel1, to2D(vn), 0));
                updateClosest4(bestIds, bestDists, p, nIds.x, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.y, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.z, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.w, iChannel0);
            }
        }
        // Light refresh: single very cheap step on non-update frames
        else if (DO_LIGHT_REFRESH == 1) {
            const int s = LIGHT_STEP;
            for (int dz = -1; dz <= 1; ++dz)
            for (int dy = -1; dy <= 1; ++dy)
            for (int dx = -1; dx <= 1; ++dx) {
                if (dx == 0 && dy == 0 && dz == 0) continue;
                ivec3 vn = v + ivec3(dx, dy, dz) * s;
                if (any(lessThan(vn, ivec3(0))) || any(greaterThanEqual(vn, ivec3(VOXEL_DIM)))) continue;
                ivec4 nIds = ivec4(texelFetch(iChannel1, to2D(vn), 0));
                updateClosest4(bestIds, bestDists, p, nIds.x, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.y, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.z, iChannel0);
                updateClosest4(bestIds, bestDists, p, nIds.w, iChannel0);
            }
        }
    }

    fragColor = vec4(bestIds);
}

/*==============================================================================
COMMON — Shared definitions, mapping, math & helpers
==============================================================================

ROLE
• Centralizes constants, enums, atlas/voxel mapping, periodic distance,
  noise/turbulence, PCA helper, and dithering so all passes stay consistent.

KEY DEFINES (excerpt)
• MAX_SITES, CUBE_SIZE, visual constants, controller thresholds (TH_LO/TH_HI).
• SITE_ATLAS_W/H: 2D layout of the site buffer (pos.xyz, R).
• VOXEL_DIM=64, SLICES_PER_ROW=8: 64×64×64 voxel grid → 512×512 atlas.

MAPPING HELPERS (ATLAS & VOXELS)
• siteUV(id)       : site ID → (x,y) pixel in site atlas.
• getSiteData(s,id): safe fetch of (pos.xyz, R) with guard for invalid IDs.
• from2D()/to2D()  : 2D pixel ↔ 3D voxel coord in the fixed 8×8 slice layout.
• voxelToWorld()   : voxel center → world position in [-CUBE_SIZE, +CUBE_SIZE].

PERIODIC SPACE (SEAMLESS)
• boundaryDelta(a,b,2*CUBE_SIZE) / boundaryDist(a,b,2*CUBE_SIZE)
  implement toroidal wrapping so edges have no cracks.

MATH/NOISE UTILITIES
• snoise() + curlNoise(): divergence-free turbulence field for Buffer D.
• getEigenSystem(): extracts smallest-eigenvector direction and eigenvalues
  for PCA-based anisotropy/aspect in Buffer D.
• hash33(): symmetric 3D hash in [-1,1]^3 for uniform seeding in Buffer A.
• bayer4x4(): ordered dithering for Image transparency/fade.

DOWNSTREAM CONTRACT
• All passes use boundaryDist for consistency in periodic space.
• Buffer B writes vec4(-1) for OOB/invalid; consumers ignore < 0 IDs.

RESULT
• A single source of truth for layout, wrapping, and math that keeps buffers
  interoperable and eliminates subtle atlas/periodicity bugs.
==============================================================================*/


// ===== Master Controls =====
#define MAX_SITES         30000
#define CUBE_SIZE         0.575
#define AUTO_ROTATE_SPEED 0.125

// ===== Physics (used by Buffer D) =====
#define STEERING_STRENGTH   0.15
#define REPULSION_STRENGTH  0.0015
