void sort4(inout float m0,inout float m1,inout float m2,inout float m3, inout int i0,inout int i1,inout int i2,inout int i3){
    if(m1<m0){ float tm=m0; m0=m1; m1=tm; int ti=i0; i0=i1; i1=ti; }
    if(m2<m1){ float tm=m1; m1=m2; m2=tm; int ti=i1; i1=i2; i2=ti; }
    if(m3<m2){ float tm=m2; m2=m3; m3=tm; int ti=i2; i2=i3; i3=ti; }
    if(m1<m0){ float tm=m0; m0=m1; m1=tm; int ti=i0; i0=i1; i1=ti; }
    if(m2<m1){ float tm=m1; m1=m2; m2=tm; int ti=i1; i1=i2; i2=ti; }
    if(m1<m0){ float tm=m0; m0=m1; m1=tm; int ti=i0; i0=i1; i1=ti; }
}
