// Noise & helpers
vec3 mod289(vec3 x){return x-floor(x*(1./289.))*289.;}
vec4 mod289(vec4 x){return x-floor(x*(1./289.))*289.;}
vec4 permute(vec4 x){return mod289(((x*34.)+1.)*x);}
vec4 taylorInvSqrt(vec4 r){return 1.79284291400159-.85373472095314*r;}
float snoise(vec3 v){
    const vec2 C=vec2(1./6.,1./3.); const vec4 D=vec4(0.,.5,1.,2.);
    vec3 i=floor(v+dot(v,C.yyy)); vec3 x0=v-i+dot(i,C.xxx);
    vec3 g=step(x0.yzx,x0.xyz); vec3 l=1.-g; vec3 i1=min(g.xyz,l.zxy); vec3 i2=max(g.xyz,l.zxy);
    vec3 x1=x0-i1+C.xxx; vec3 x2=x0-i2+C.yyy; vec3 x3=x0-D.yyy; i=mod289(i);
    vec4 p=permute(permute(permute(i.z+vec4(0.,i1.z,i2.z,1.))+i.y+vec4(0.,i1.y,i2.y,1.))+i.x+vec4(0.,i1.x,i2.x,1.));
    float n_=.142857142857; vec3 ns=n_*D.wyz-D.xzx; vec4 j=p-49.*floor(p*ns.z*ns.z);
    vec4 x_=floor(j*ns.z); vec4 y_=floor(j-7.*x_); vec4 x=x_*ns.x+ns.yyyy; vec4 y=y_*ns.x+ns.yyyy;
    vec4 h=1.-abs(x)-abs(y); vec4 b0=vec4(x.xy,y.xy); vec4 b1=vec4(x.zw,y.zw);
    vec4 s0=floor(b0)*2.+1.; vec4 s1=floor(b1)*2.+1.; vec4 sh=-step(h,vec4(0.));
    vec4 a0=b0.xzyw+s0.xzyw*sh.xxyy; vec4 a1=b1.xzyw+s1.xzyw*sh.zzww;
    vec3 p0=vec3(a0.xy,h.x); vec3 p1=vec3(a0.zw,h.y); vec3 p2=vec3(a1.xy,h.z); vec3 p3=vec3(a1.zw,h.w);
    vec4 norm=taylorInvSqrt(vec4(dot(p0,p0),dot(p1,p1),dot(p2,p2),dot(p3,p3)));
    p0*=norm.x; p1*=norm.y; p2*=norm.z; p3*=norm.w; vec4 m=max(.6-vec4(dot(x0,x0),dot(x1,x1),dot(x2,x2),dot(x3,x3)),0.); m=m*m;
    return 42.*dot(m*m,vec4(dot(p0,x0),dot(p1,x1),dot(p2,x2),dot(p3,x3)));
}
vec3 curlNoise(vec3 p){
    const float e=.1;
    float n1=snoise(vec3(p.x,p.y+e,p.z)), n2=snoise(vec3(p.x,p.y-e,p.z));
    float n3=snoise(vec3(p.x,p.y,p.z+e)), n4=snoise(vec3(p.x,p.y,p.z-e));
    float n5=snoise(vec3(p.x+e,p.y,p.z)), n6=snoise(vec3(p.x-e,p.y,p.z));
    float x=n2-n1-(n4-n3), y=n4-n3-(n6-n5), z=n6-n5-(n2-n1);
    return normalize(vec3(x,y,z));
}
vec3 hash31(int n){ uvec3 u=uvec3(n,n*16807,n*48271); u=u.yzx*u.zxy; u=u^(u>>16); return vec3(u)/float(0xffffffffU)*2.-1.; }

void getEigenSystem(mat3 M,out vec3 eigvals,out vec3 eigvec_min){
    float m=(M[0][0]+M[1][1]+M[2][2])/3.;
    M[0][0]-=m; M[1][1]-=m; M[2][2]-=m;
    float p=(M[0][0]*M[0][0]+M[1][1]*M[1][1]+M[2][2]*M[2][2]+2.*(M[0][1]*M[0][1]+M[0][2]*M[0][2]+M[1][2]*M[1][2]))/6.;
    float det=determinant(M); float r=det/(2.*pow(max(p,1e-9),1.5)); r=clamp(r,-1.,1.);
    float phi=acos(r)/3.; float p_sqrt=sqrt(p);
    eigvals.x=m+2.*p_sqrt*cos(phi);
    eigvals.y=m+2.*p_sqrt*cos(phi+2.09439510239);
    eigvals.z=m+2.*p_sqrt*cos(phi+4.18879020478);
    float l_min=min(eigvals.x,min(eigvals.y,eigvals.z));
    mat3 A=M; A[0][0]-=l_min; A[1][1]-=l_min; A[2][2]-=l_min;
    vec3 r0=vec3(A[0][0],A[0][1],A[0][2]);
    vec3 r1=vec3(A[1][0],A[1][1],A[1][2]);
    vec3 r2=vec3(A[2][0],A[2][1],A[2][2]);
    vec3 c01=cross(r0,r1), c12=cross(r1,r2), c20=cross(r2,r0), result_vec;
    if(dot(c01,c01)>dot(c12,c12)&&dot(c01,c01)>dot(c20,c20)) result_vec=c01;
    else if(dot(c12,c12)>dot(c20,c20)) result_vec=c12; else result_vec=c20;
    eigvec_min = (dot(result_vec,result_vec)<1e-12) ? vec3(0.) : normalize(result_vec);
}


// Symmetric 3D hash in [-1,1]^3
vec3 hash33(vec3 p3){
    p3 = fract(p3 * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz + 33.33);
    return -1.0 + 2.0 * fract(vec3(
        (p3.x + p3.y) * p3.z,
        (p3.x + p3.z) * p3.y,
        (p3.y + p3.z) * p3.x
    ));
}

// Voxel layout helpers
ivec3 from2D(ivec2 t){
    int sX=t.x/VOXEL_DIM; int sY=t.y/VOXEL_DIM; int z=sY*SLICES_PER_ROW+sX;
    return ivec3(t.x%VOXEL_DIM, t.y%VOXEL_DIM, z);
}
ivec2 to2D(ivec3 c){
    int sX=c.z%SLICES_PER_ROW; int sY=c.z/SLICES_PER_ROW;
    return ivec2(sX*VOXEL_DIM + c.x, sY*VOXEL_DIM + c.y);
}
vec3 voxelToWorld(ivec3 c){
    return (vec3(c)+.5)/float(VOXEL_DIM)*2.*CUBE_SIZE - CUBE_SIZE;
}
float bayer4x4(vec2 p){
    const mat4 b=mat4(0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5)/16.;
    ivec2 i=ivec2(mod(p*DITHER_SCALE,4.)); return b[i.x][i.y];
}

/*==============================================================================
BUFFER D — Shape analysis (PCA) & physics (repulsion, turbulence, steering)
==============================================================================

WHAT THIS PASS PRODUCES
• Per-site velocity and a smoothed anisotropy measure:
  fragColor = vec4(vel.xyz, smoothed_aspect).

NEIGHBORHOOD GATHER
• Convert site position to voxel coord; scan a 3×3×3 block (periodic wrap).
• Pull up to 4 IDs per neighbor voxel from Buffer B; keep nearest distinct
  candidates (up to NEIGHBOR_COUNT) by periodic distance.

PCA → ANISOTROPY & DIRECTION
• Build covariance of neighbor offsets (periodic delta).
• Extract eigenvalues and smallest-eigenvector (dirMin).
• Aspect ≈ sqrt(l_max / l_min); higher means more elongated.

FORCES
• Repulsion: for each neighbor, if distance < (Ra+Rb)*RADIUS_INFLATION,
  push along the connecting direction by overlap * REPULSION_STRENGTH.
• Turbulence: add curlNoise(pos * TURBULENCE_SCALE) * TURBULENCE_STRENGTH.
• Steering (toggle): if USE_STEERING==1, add dirMin * STEER_GAIN * (aspect-1).

INTEGRATION & LIMITS
• Apply friction, clamp to MAX_SPEED.
• Exponentially smooth aspect into D.w with ASPECT_ALPHA.

INPUTS / OUTPUTS
• iChannel0 → previous Buffer D (vel, smoothed_aspect)
• iChannel1 → Buffer A (pos.xyz, R)
• iChannel2 → Buffer B (4 nearest IDs per voxel)
• fragColor → vec4(vel.xyz, smoothed_aspect)

RESULT
• Stable velocities reacting to local packing pressure and (optionally) to the
  cell’s most compressed direction; plus a clean, low-noise aspect signal for A/Image.
==============================================================================*/



/*==============================================================================
BUFFER D — Shape Analysis & Physics (with steering switch)
==============================================================================*/


#define USE_STEERING 1        // 1 = ON, 0 = OFF
#define STEER_GAIN   2.5     // steering strength
const float ASPECT_ALPHA = 0.08;


ivec3 wrapVoxelD(ivec3 v){
    return ivec3( ((v.x%VOXEL_DIM)+VOXEL_DIM)%VOXEL_DIM,
                  ((v.y%VOXEL_DIM)+VOXEL_DIM)%VOXEL_DIM,
                  ((v.z%VOXEL_DIM)+VOXEL_DIM)%VOXEL_DIM );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    ivec2 p = ivec2(fragCoord);
    if (p.x >= SITE_ATLAS_W || p.y >= SITE_ATLAS_H) { fragColor = vec4(0.0); return; }
    int siteId = p.y * SITE_ATLAS_W + p.x;
    if (siteId >= MAX_SITES) { fragColor = vec4(0.0); return; }

    // Previous D (vel + aspect)
    vec4 prevD = texelFetch(iChannel0, p, 0);
    vec3 vel   = (iFrame < 5) ? vec3(0.0) : prevD.xyz;
    float prev_aspect = (iFrame < 5) ? 1.0 : prevD.w;

    // Self state
    vec4 selfA = texelFetch(iChannel1, p, 0);
    vec3 pos   = selfA.xyz;
    float Ra   = selfA.w;
    float space = CUBE_SIZE * 2.0;

    // Neighbor gather (3×3×3 voxels)
    ivec3 center = ivec3(floor((pos/space + .5) * float(VOXEL_DIM)));
    int   nIDs[NEIGHBOR_COUNT];   for(int i=0;i<NEIGHBOR_COUNT;i++) nIDs[i]=-1;
    float nDists[NEIGHBOR_COUNT]; for(int i=0;i<NEIGHBOR_COUNT;i++) nDists[i]=1e6;
    vec3  nPos [NEIGHBOR_COUNT];

    for (int z=-1; z<=1; z++)
    for (int y=-1; y<=1; y++)
    for (int x=-1; x<=1; x++) {
        ivec3 nc = wrapVoxelD(center + ivec3(x,y,z));
        ivec4 ids = ivec4(texelFetch(iChannel2, to2D(nc), 0));
        int cand[4]; cand[0]=ids.x; cand[1]=ids.y; cand[2]=ids.z; cand[3]=ids.w;
        for (int j=0;j<4;j++) {
            int nid=cand[j]; if (nid<0 || nid==siteId) continue;
            vec3 q = getSiteData(iChannel1, nid).xyz;
            float d = boundaryDist(pos, q, space);
            if (d < nDists[NEIGHBOR_COUNT-1]) {
                nDists[NEIGHBOR_COUNT-1]=d; nIDs[NEIGHBOR_COUNT-1]=nid; nPos[NEIGHBOR_COUNT-1]=q;
                for (int k=NEIGHBOR_COUNT-2; k>=0; --k) {
                    if (nDists[k+1] < nDists[k]) {
                        float td=nDists[k]; nDists[k]=nDists[k+1]; nDists[k+1]=td;
                        int   ti=nIDs[k];   nIDs[k]=nIDs[k+1];     nIDs[k+1]=ti;
                        vec3  tp=nPos[k];   nPos[k]=nPos[k+1];     nPos[k+1]=tp;
                    } else break;
                }
            }
        }
    }

    // PCA → aspect + dirMin
    int M = 0; for (int i=0;i<NEIGHBOR_COUNT;i++) if (nIDs[i]>=0) M++;
    float aspect = 1.0;
    vec3  dirMin = vec3(0.0);

    if (M > 3) {
        mat3 cov = mat3(0.0);
        for (int i=0;i<M;i++) {
            vec3 d = boundaryDelta(nPos[i], pos, space);
            cov[0][0]+=d.x*d.x; cov[0][1]+=d.x*d.y; cov[0][2]+=d.x*d.z;
            cov[1][1]+=d.y*d.y; cov[1][2]+=d.y*d.z;
            cov[2][2]+=d.z*d.z;
        }
        cov[1][0]=cov[0][1]; cov[2][0]=cov[0][2]; cov[2][1]=cov[1][2];
        vec3 eigvals; getEigenSystem(cov, eigvals, dirMin);
        float lmax=max(eigvals.x, max(eigvals.y, eigvals.z));
        float lmin=min(eigvals.x, min(eigvals.y, eigvals.z));
        if (lmin > 1e-7) aspect = sqrt(lmax/lmin);
    }

    // Repulsion (pressure)
    vec3 rep = vec3(0.0);
    for (int i=0;i<M;i++) {
        float Rb = getSiteData(iChannel1, nIDs[i]).w;
        float ideal = (Ra + Rb) * RADIUS_INFLATION;
        float d = nDists[i];
        if (d > 1e-6 && d < ideal) {
            float overlap = ideal - d;
            vec3 dir = boundaryDelta(pos, nPos[i], space) / d;
            rep += dir * overlap * REPULSION_STRENGTH;
        }
    }

    // Turbulence
    vec3 turb = curlNoise(pos * TURBULENCE_SCALE) * TURBULENCE_STRENGTH;

    // Integrate velocity
    vel += rep + turb;

#if USE_STEERING
    // Steering only if switch enabled
    vel += dirMin * STEER_GAIN * (aspect - 1.0);
#endif

    vel *= (1.0 - FRICTION);
    float L = length(vel);
    if (L > MAX_SPEED) vel *= (MAX_SPEED / max(L, 1e-9));

    // Smooth aspect
    float smoothed_aspect = mix(prev_aspect, aspect, ASPECT_ALPHA);

    fragColor = vec4(vel, smoothed_aspect);
}

/*==============================================================================
BUFFER C — Size/spacing metric for visualization (band-pass helper)
==============================================================================

WHAT THIS PASS PRODUCES
• For each site ID (same atlas as A/D), writes a normalized spacing ratio:
  fragColor.r = clamp( averageNeighborDistance / averageIdealSpacing, 0..1 )
  (Other channels unused.)

HOW IT’S COMPUTED
1) Locate the site’s voxel cell and collect candidates from a 3×3×3 block of
   voxels around it (periodic wrap). Candidate IDs come from Buffer B’s
   4-nearest list per voxel.
2) Maintain the NEIGHBOR_COUNT nearest distinct neighbors by periodic distance.
3) Compute:
   • avgN = average of periodic distances to those neighbors.
   • avgI = average of (Ra + Rb) * RADIUS_INFLATION for the same neighbors.
   • spacingRatio = (avgN / avgI), then normalize to [0,1] by dividing RATIO_MAX.

INPUTS / OUTPUTS
• iChannel0 → Buffer A (pos.xyz, R)
• iChannel1 → Buffer B (4 nearest IDs per voxel)
• fragColor → vec4(norm_ratio, 0, 0, 1)

RESULT
• A smooth per-site scalar indicating local crowding vs ideal packing. The
  Image pass can use it for optional band-pass visibility/opacity.
==============================================================================*/


/*==============================================================================
BUFFER C — Size/Spacing Metric for Viz
Inputs:
  iChannel0 = Buffer A (pos.xyz, R)
  iChannel1 = Buffer B (4 nearest IDs per voxel)
Output:
  .r = norm_ratio = clamp( spacingRatio / RATIO_MAX, 0..1 )
==============================================================================*/

const float RATIO_MAX = 2.0; // keep in sync with Image/D if you use band-pass

ivec3 wrapVoxelC(ivec3 v){
    return ivec3( ( (v.x%VOXEL_DIM)+VOXEL_DIM)%VOXEL_DIM,
                  ( (v.y%VOXEL_DIM)+VOXEL_DIM)%VOXEL_DIM,
                  ( (v.z%VOXEL_DIM)+VOXEL_DIM)%VOXEL_DIM );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    ivec2 p = ivec2(fragCoord);
    if (p.x >= SITE_ATLAS_W || p.y >= SITE_ATLAS_H) { fragColor = vec4(0.0); return; }
    int siteId = p.y * SITE_ATLAS_W + p.x;
    if (siteId >= MAX_SITES) { fragColor = vec4(0.0); return; }

    vec4 selfA = texelFetch(iChannel0, p, 0);
    vec3 pos   = selfA.xyz;
    float Ra   = selfA.w;
    float space = CUBE_SIZE * 2.0;

    ivec3 center = ivec3(floor((pos/space + .5) * float(VOXEL_DIM)));

    int   nIDs[NEIGHBOR_COUNT];   for (int i=0;i<NEIGHBOR_COUNT;i++) nIDs[i]  = -1;
    float nDists[NEIGHBOR_COUNT]; for (int i=0;i<NEIGHBOR_COUNT;i++) nDists[i]= 1e6;

    // Pull candidates from 3x3x3 voxels (periodic)
    for (int z=-1; z<=1; z++)
    for (int y=-1; y<=1; y++)
    for (int x=-1; x<=1; x++) {
        ivec3 nc = wrapVoxelC(center + ivec3(x,y,z));
        ivec4 ids = ivec4(texelFetch(iChannel1, to2D(nc), 0));
        for (int j=0; j<4; j++) {
            int nid = (j==0)?ids.x : (j==1)?ids.y : (j==2)?ids.z : ids.w;
            if (nid < 0 || nid == siteId) continue;
            vec3 nPos = getSiteData(iChannel0, nid).xyz;
            float d = boundaryDist(pos, nPos, space);
            if (d < nDists[NEIGHBOR_COUNT-1]) {
                nDists[NEIGHBOR_COUNT-1] = d; nIDs[NEIGHBOR_COUNT-1] = nid;
                for (int k=NEIGHBOR_COUNT-2; k>=0; --k) {
                    if (nDists[k+1] < nDists[k]) {
                        float td=nDists[k]; nDists[k]=nDists[k+1]; nDists[k+1]=td;
                        int   ti=nIDs[k];   nIDs[k]=nIDs[k+1];     nIDs[k+1]=ti;
                    } else break;
                }
            }
        }
    }

    int M = 0;
    float avgN = 0.0, avgI = 0.0;
    for (int i=0;i<NEIGHBOR_COUNT;i++) {
        int nid = nIDs[i]; if (nid < 0) break;
        M++;
        float Rb = getSiteData(iChannel0, nid).w;
        avgN += nDists[i];
        avgI += (Ra + Rb) * RADIUS_INFLATION;
    }
    float spacingRatio = 1.0;
    if (M > 0 && avgI > 1e-6) { avgN /= float(M); avgI /= float(M); spacingRatio = avgN / avgI; }

    float norm_ratio = clamp(spacingRatio / RATIO_MAX, 0.0, 1.0);
    fragColor = vec4(norm_ratio, 0.0, 0.0, 1.0);
}
